    # ==========================================
    # DAY 09: Multi-Agent Systems, MCP & A2A
    # ==========================================
    d09_easy = [
        ("Multi-Agent Foundations", "Hệ thống Đa Đại lý (Multi-Agent System - MAS) trong AI là gì?",
         ["Nhiều máy tính nối chung 1 dây nguồn", "Hệ thống gồm nhiều AI Agent chuyên biệt phối hợp làm việc với nhau, mỗi Agent đảm nhận một vai trò hoặc kỹ năng cụ thể để cùng giải quyết bài toán phức tạp", "Một Agent chạy 10 lần liên tục", "Một trang web có nhiều nút bấm"], 1,
         "Multi-Agent phân rã bài toán lớn thành các phần việc nhỏ cho các Agent chuyên trách (e.g. Researcher, Coder, Reviewer) cộng tác giải quyết.", "Day 09 - Slide: Multi-Agent Systems Foundations"),
        ("Model Context Protocol (MCP)", "Giao thức Model Context Protocol (MCP) do Anthropic khởi xướng là gì?",
         ["Một loại dây cáp mạng mới", "Một chuẩn giao thức mở (Open Standard) cho phép các ứng dụng AI kết nối an toàn và đồng nhất với các nguồn dữ liệu, công cụ và môi trường phát triển bên ngoài", "Một ngôn ngữ lập trình mới", "Một hệ điều hành thay thế Windows"], 1,
         "MCP chuẩn hóa cách các mô hình AI giao tiếp với Tools và Data Sources qua một giao diện chung, tương tự như USB-C cho AI.", "Day 09 - Slide: Model Context Protocol (MCP) Overview"),
        ("MCP Architecture", "Ba thành phần cốt lõi trong kiến trúc Model Context Protocol (MCP) là gì?",
         ["CPU, RAM, Hard Drive", "MCP Host (Ứng dụng AI như Claude Desktop/IDE), MCP Client (Module kết nối trung gian), và MCP Server (Dịch vụ cung cấp Tools/Resources)", "HTML, CSS, JavaScript", "Input, Hidden Layer, Output"], 1,
         "Kiến trúc MCP gồm Host (chứa LLM), Client (quản lý kết nối) và Server (chứa công cụ/dữ liệu thực tế).", "Day 09 - Slide: MCP Architecture Components"),
        ("MCP Capabilities", "Ba loại năng lực cơ bản (Primitives) mà một MCP Server có thể cung cấp cho AI Client là gì?",
         ["Video, Âm thanh, Hình ảnh", "Resources (Dữ liệu/Tài liệu có cấu trúc), Tools (Hàm thực thi có tác dụng phụ), và Prompts (Khuôn mẫu tương tác định sẵn)", "Mouse, Keyboard, Monitor", "File, Folder, Drive"], 1,
         "MCP quy định 3 khối tài nguyên chuẩn: Resources (đọc dữ liệu), Tools (thực thi hành động) và Prompts (hướng dẫn mẫu).", "Day 09 - Slide: MCP Primitives (Resources, Tools, Prompts)"),
        ("MCP Transport Layer", "Hai giao thức truyền tải (Transports) chuẩn được MCP hỗ trợ chính thức là gì?",
         ["Bluetooth và Hồng ngoại", "Stdio (Standard Input/Output cho kết nối cục bộ) và SSE / HTTP (Server-Sent Events cho kết nối từ xa qua mạng)", "FTP và Telnet", "Bưu điện và Fax"], 1,
         "MCP hỗ trợ Stdio (giao tiếp tiến trình cục bộ an toàn) và SSE/HTTP (kết nối dịch vụ phân tán qua mạng).", "Day 09 - Slide: MCP Transport Protocols"),
        ("Multi-Agent Patterns: Supervisor", "Mô hình kiến trúc 'Supervisor Agent' (Agent Giám sát) hoạt động như thế nào?",
         ["Supervisor Agent trực tiếp làm tất cả mọi việc", "Supervisor Agent tiếp nhận yêu cầu tổng thể từ người dùng, đánh giá trạng thái và quyết định phân công nhiệm vụ cho Agent chuyên trách nào tiếp theo", "Supervisor Agent chỉ làm nhiệm vụ tắt máy", "Các Agent con ra lệnh cho Supervisor"], 1,
         "Supervisor Pattern sử dụng một Agent trung tâm điều phối luồng làm việc và định tuyến công việc cho các Worker Agents.", "Day 09 - Slide: Supervisor Agent Pattern"),
        ("Multi-Agent Patterns: Peer-to-Peer", "Mô hình 'Peer-to-Peer / Swarm' trong Multi-Agent khác biệt với Supervisor ở điểm nào?",
         ["P2P không có LLM", "P2P là mạng lưới phi tập trung, các Agent có thể trực tiếp gửi tin nhắn hoặc chuyển giao quyền điều khiển (Handoff) cho Agent khác mà không cần thông qua một Supervisor trung tâm", "P2P chỉ chạy được trên điện thoại", "P2P bắt buộc phải có 100 Agent"], 1,
         "Trong kiến trúc Swarm/P2P, các Agent tự do trao đổi và chuyển quyền thực thi dựa trên trạng thái hội thoại và công cụ handoff.", "Day 09 - Slide: Peer-to-Peer & Swarm Patterns"),
        ("Agent-to-Agent (A2A) Communication", "Định dạng trao đổi thông điệp phổ biến nhất giữa các Agent trong hệ thống Multi-Agent là gì?",
         ["Mã Morse", "JSON-RPC 2.0 hoặc Chuỗi tin nhắn Chat có cấu trúc (Messages with Roles & Metadata)", "File ảnh chụp màn hình", "Sóng âm thanh"], 1,
         "Các Agent giao tiếp với nhau bằng tin nhắn có cấu trúc JSON rõ ràng quy định người gửi (Sender), người nhận (Recipient), nội dung (Content) và hành động (Action).", "Day 09 - Slide: Agent-to-Agent Messaging Protocols"),
        ("Multi-Agent Token Overhead", "Tại sao hệ thống Multi-Agent thường tiêu tốn lượng token gấp 3 đến 10 lần so với Single Agent?",
         ["Vì máy chủ OpenAI tính tiền phạt", "Vì mỗi Agent trong nhóm cần có System Prompt riêng và lịch sử trao đổi qua lại giữa các Agent liên tục được nạp vào context của từng lượt gọi LLM", "Vì các Agent tự động tải video về xem", "Vì số lượng ký tự trong từ điển tăng lên"], 1,
         "Giao tiếp đa chiều giữa các tác tử (Inter-agent Dialogue) làm phình to số lượng token input trên mỗi vòng lặp giải quyết bài toán.", "Day 09 - Slide: Multi-Agent Token Economics"),
        ("Agent Handoff Mechanism", "Cơ chế 'Handoff' (Chuyển giao quyền điều khiển) trong Swarm hoạt động như thế nào?",
         ["Tắt máy và mở lại", "Một Agent gọi một hàm đặc biệt (e.g. `transfer_to_support_agent()`), kết quả của hàm này sẽ chuyển đổi active agent hiện tại sang agent mới kèm theo toàn bộ ngữ cảnh hội thoại", "Bắt người dùng phải đăng xuất", "Gửi email cho ban quản trị"], 1,
         "Handoff cho phép chuyển tiếp liền mạch người dùng từ Agent này sang Agent khác (ví dụ: từ Triage Agent sang Billing Agent) trong một phiên duy nhất.", "Day 09 - Slide: Agent Handoff Patterns"),
        ("MCP Tool Discovery", "Trong MCP, làm thế nào Client biết được Server đang cung cấp những công cụ nào?",
         ["Client phải tự đoán", "Client gửi yêu cầu `tools/list` qua JSON-RPC và Server sẽ phản hồi danh sách định nghĩa các công cụ cùng JSON Schema tham số tương ứng", "Server in danh sách ra máy in", "Client phải đọc mã nguồn của Server"], 1,
         "Phương thức `tools/list` trong chuẩn MCP cho phép khám phá động danh sách công cụ và schema tương ứng theo thời gian thực.", "Day 09 - Slide: MCP Dynamic Tool Discovery"),
        ("Multi-Agent Frameworks", "Frameworks mã nguồn mở phổ biến nào sau đây chuyên biệt cho việc xây dựng hệ thống Multi-Agent?",
         ["LangGraph, AutoGen, CrewAI", "Photoshop, Premiere, Illustrator", "MySQL, MongoDB, Redis", "Docker, Kubernetes, Terraform"], 0,
         "LangGraph, AutoGen (Microsoft) và CrewAI là các framework hàng đầu thế giới trong việc lập trình và điều phối hệ thống Multi-Agent.", "Day 09 - Slide: Multi-Agent Frameworks Ecosystem"),
        ("Agent Specialization", "Tại sao việc chia nhỏ tác vụ cho các 'Agent Chuyên biệt' (Specialized Agents) lại cho kết quả tốt hơn việc dùng 1 'Agent Vạn năng' (Monolithic Agent)?",
         ["Vì chia nhỏ giúp máy tính chạy mát hơn", "Vì mỗi Agent chuyên biệt có System Prompt ngắn gọn, tập trung cao độ vào một miền tri thức hẹp và chỉ cần bộ công cụ nhỏ, giảm thiểu sự nhầm lẫn và hallucination", "Vì các công ty thích tuyển nhiều nhân viên", "Vì mô hình lớn bị cấm làm nhiều việc"], 1,
         "Chuyên môn hóa giúp tối ưu hóa không gian Attention và giới hạn phạm vi công cụ (Tool Scoping), nâng cao tỉ lệ thành công của từng tác vụ con.", "Day 09 - Slide: Benefits of Agent Specialization"),
        ("Multi-Agent Infinite Loop", "Nguy cơ lớn nhất khi 2 Agent tự do trò chuyện với nhau mà không có điều kiện dừng rõ ràng là gì?",
         ["Máy tính tự động format ổ cứng", "Vòng lặp bất tận (Infinite Ping-Pong Loop): Hai Agent liên tục khen ngợi hoặc hỏi đáp qua lại không hồi kết, làm cạn kiệt ngân sách token trong vài phút", "Giao diện chuyển sang màu hồng", "Mất kết nối Bluetooth"], 1,
         "Thiếu điều kiện dừng hoặc thiếu cơ chế giám sát số bước tối đa có thể khiến 2 Agent rơi vào trạng thái bẫy lặp giao tiếp vô nghĩa.", "Day 09 - Slide: Multi-Agent Loop Prevention"),
        ("MCP Security Sandbox", "Tại sao MCP Server cần được chạy trong môi trường bảo mật có kiểm soát quyền truy cập?",
         ["Để file không bị xóa nhầm", "Vì MCP Server có thể cung cấp các công cụ đọc/ghi tệp tin hoặc truy cập cơ sở dữ liệu trên máy tính người dùng; cần phân quyền rõ ràng để tránh bị khai thác độc hại", "Để tăng tốc độ đọc của ổ cứng", "Để tuân thủ luật giao thông"], 1,
         "MCP Server tương tác trực tiếp với tài nguyên hệ thống thực tế, đòi hỏi cơ chế xác thực và cấp quyền tối thiểu (Least Privilege).", "Day 09 - Slide: MCP Security & Sandboxing")
    ]

    d09_med = [
        ("Multi-Agent State Sharing", "Trong LangGraph, làm thế nào trạng thái (Shared State) được cập nhật một cách an toàn khi nhiều Agent cùng tham gia xử lý?",
         ["Mỗi Agent tự tạo một file text riêng", "Sử dụng Cấu trúc Trạng thái tập trung (State Graph Schema) với các hàm Reducer (như `operator.add` để nối thêm tin nhắn vào lịch sử), đảm bảo các Agent cập nhật trạng thái có kiểm soát và nhất quán", "Tắt toàn bộ cơ chế bảo vệ bộ nhớ", "Ghi đè ngẫu nhiên vào RAM"], 1,
         "Reducers trong LangGraph quy định cách thức tích hợp dữ liệu mới từ các nút (Nodes/Agents) vào trạng thái chung của đồ thị một cách an toàn và có thể dự đoán.", "Day 09 - Slide: Shared State Management in LangGraph"),
        ("MCP Protocol: JSON-RPC 2.0", "Cấu trúc một gói tin yêu cầu thực thi công cụ (`tools/call`) trong giao thức MCP tuân thủ chuẩn JSON-RPC 2.0 có định dạng như thế nào?",
         ["Chuỗi văn bản tự do", "`{ 'jsonrpc': '2.0', 'id': 1, 'method': 'tools/call', 'params': { 'name': 'query_db', 'arguments': { 'sql': 'SELECT 1' } } }`", "Mã nhị phân Base64", "File XML bọc trong HTML"], 1,
         "MCP chuẩn hóa mọi cuộc gọi dựa trên đặc tả JSON-RPC 2.0 với đầy đủ các trường `jsonrpc`, `id`, `method` và `params`.", "Day 09 - Slide: MCP JSON-RPC 2.0 Specification"),
        ("Agent Consensus: Majority Voting", "Khi 3 Agent phản biện (Debate Agents) đưa ra 3 kết luận khác nhau về một báo cáo tài chính, cơ chế giải quyết xung đột nào thường được áp dụng?",
         ["Chỉ chọn câu trả lời của Agent có tên dài nhất", "Áp dụng Cơ chế Bỏ phiếu Đồng thuận (Majority Voting) hoặc chuyển toàn bộ lập luận của 3 Agent cho một 'Judge/Arbitrator Agent' độc lập để đưa ra phán quyết cuối cùng", "Xóa toàn bộ báo cáo và từ chối trả lời", "Chọn câu trả lời ngắn nhất"], 1,
         "Judge Agent hoặc Majority Voting giúp tổng hợp các góc nhìn đa chiều và đưa ra quyết định khách quan dựa trên sức nặng của bằng chứng.", "Day 09 - Slide: Agent Debate & Consensus Mechanisms"),
        ("MCP Dynamic Resource Subscriptions", "Tính năng 'Resource Subscriptions' trong Model Context Protocol cho phép MCP Client thực hiện điều gì?",
         ["Mua hàng giảm giá trên mạng", "Đăng ký theo dõi một tài nguyên (ví dụ: file log, trạng thái server); khi tài nguyên này thay đổi, MCP Server sẽ tự động gửi thông báo cập nhật thời gian thực (Push Notification) cho Client", "Đăng ký nhận email quảng cáo", "Tự động đổi mật khẩu máy chủ"], 1,
         "Subscriptions trong MCP cho phép AI Client luôn cập nhật trạng thái mới nhất của tài nguyên môi trường mà không cần liên tục gửi lệnh hỏi (Polling).", "Day 09 - Slide: MCP Resource Subscriptions"),
        ("Hierarchical Task Decomposition", "Trong mô hình Plan-and-Execute Multi-Agent, vai trò của 'Planner Agent' và 'Replanner Agent' phối hợp như thế nào?",
         ["Cả hai đều làm cùng một việc gõ code", "Planner Agent phân rã mục tiêu lớn thành chuỗi các bước con; Replanner Agent theo dõi tiến độ thực thi thực tế của các Worker, nếu phát hiện thất bại ở bước nào thì tự động điều chỉnh lại danh sách các bước còn lại", "Planner Agent tắt máy tính khi hoàn thành", "Replanner Agent chỉ làm nhiệm vụ xóa log"], 1,
         "Replanning linh hoạt giúp hệ thống Multi-Agent đối phó hiệu quả với các biến cố bất ngờ xảy ra trong quá trình thực thi thế giới thực.", "Day 09 - Slide: Hierarchical Task Decomposition & Replanning"),
        ("Multi-Agent Context Window Isolation", "Làm thế nào việc sử dụng Multi-Agent giúp khắc phục giới hạn Context Window so với Single-Agent?",
         ["Bằng cách tăng dung lượng RAM máy tính", "Mỗi Sub-Agent chỉ nhận phần ngữ cảnh tối thiểu cần thiết để làm nhiệm vụ của mình, xử lý xong chỉ trả về bản tóm tắt kết quả (Summary) cho Supervisor thay vì đẩy toàn bộ 50 trang tài liệu vào ngữ cảnh chung", "Bằng cách xóa toàn bộ mã nguồn của Agent", "Bằng cách chuyển dữ liệu thành file nén .zip"], 1,
         "Context Isolation ngăn chặn hiện tượng làm tràn bộ nhớ ngữ cảnh của Agent chính bằng cách phân bổ việc xử lý dữ liệu chi tiết cho các Agent con.", "Day 09 - Slide: Context Isolation in MAS"),
        ("MCP Server Implementation in Python", "Thư viện chính thức nào của Python được sử dụng để xây dựng một MCP Server tiêu chuẩn?",
         ["django", "mcp (hoặc fastmcp)", "tensorflow", "pygame"], 1,
         "`fastmcp` và SDK `mcp` chính thức cung cấp các decorator đơn giản (e.g. `@mcp.tool()`, `@mcp.resource()`) để nhanh chóng xuất bản công cụ chuẩn MCP.", "Day 09 - Slide: Building MCP Servers with Python FastMCP"),
        ("Agentic Tool Delegation Security", "Khi Agent A ủy quyền (Delegate) một tác vụ cho Agent B, rủi ro bảo mật nào phát sinh và cách kiểm soát?",
         ["Màn hình máy tính bị đổi màu", "Rủi ro 'Confused Deputy' (Ủy quyền nhầm lẫn): Agent B có thể vô tình thực thi một hành động vượt quá quyền hạn của Agent A; kiểm soát bằng cách truyền kèm Token Ủy quyền có phạm vi hẹp (Scoped Capability Token)", "Agent B tự động xóa code của Agent A", "Không có rủi ro nào"], 1,
         "Capability-based Security đảm bảo rằng quyền hạn của Agent con không bao giờ được vượt quá quyền hạn của Agent cha đã ủy quyền nó.", "Day 09 - Slide: Capability Tokens & Delegation Security"),
        ("Multi-Agent Reflection & Critique Loops", "Mô hình 'Generator-Critic Pattern' trong Multi-Agent mang lại lợi ích gì cho chất lượng mã nguồn?",
         ["Tự động tăng tốc độ gõ phím", "Generator Agent viết code ban đầu; Critic Agent phân tích tìm kiếm lỗi bảo mật, edge cases và vi phạm chuẩn phong cách (Style Guide); chu trình lặp lại cho đến khi Critic phê duyệt đạt chuẩn", "Tự động đổi ngôn ngữ lập trình", "Không mang lại lợi ích gì"], 1,
         "Phân tách rõ ràng giữa vai trò 'Sáng tạo' và vai trò 'Phản biện khắt khe' giúp nâng cao đáng kể độ tin cậy và tính an toàn của mã nguồn sinh ra.", "Day 09 - Slide: Generator-Critic Loops in MAS"),
        ("MCP vs Custom Tool Calling", "Ưu điểm vượt trội lớn nhất của việc chuẩn hóa công cụ theo chuẩn MCP so với việc viết hàm Function Calling riêng lẻ cho từng LLM là gì?",
         ["MCP làm cho code chạy nhanh hơn 1 tỷ lần", "Khả năng Tái sử dụng & Khả tương tác (Reusability & Interoperability): Một MCP Server viết một lần có thể kết nối ngay lập tức với bất kỳ ứng dụng nào hỗ trợ MCP (Claude Desktop, Cursor, Custom Agents) mà không cần viết lại code tích hợp", "MCP không cần kết nối mạng", "MCP tự động viết prompt"], 1,
         "MCP giải quyết bài toán $M \\times N$ tích hợp: M công cụ chỉ cần viết M MCP Server để phục vụ cho N ứng dụng AI khác nhau.", "Day 09 - Slide: Why Standardize on MCP"),
        ("Agent Communication Topologies", "Trong các cấu trúc mạng lưới Agent (Network Topologies), cấu trúc 'Hierarchical Mesh' (Lưới phân cấp) kết hợp ưu điểm của những mô hình nào?",
         ["Không có ưu điểm nào", "Kết hợp tính trật tự kiểm soát của mô hình Star/Supervisor ở tầng cao với sự linh hoạt trao đổi trực tiếp giữa các Worker ở tầng thấp (Clustered Collaboration)", "Làm tăng độ trễ lên gấp 10 lần", "Làm mất toàn bộ dữ liệu"], 1,
         "Hierarchical Mesh cho phép các nhóm Agent con tự do phối hợp cục bộ trong khi vẫn duy trì sự định hướng tổng thể từ tầng quản lý.", "Day 09 - Slide: Agent Communication Topologies"),
        ("Multi-Agent Deadlock Detection Algorithms", "Làm thế nào hệ thống điều phối phát hiện tình trạng 'Deadlock' khi Agent A chờ kết quả từ Agent B, trong khi Agent B lại đang chờ dữ liệu từ Agent A?",
         ["Tắt nguồn máy chủ", "Xây dựng Đồ thị Phụ thuộc Đợi (Wait-For Graph) theo thời gian thực và áp dụng thuật toán tìm chu trình (Cycle Detection như Tarjan hoặc DFS); nếu phát hiện chu trình phụ thuộc, kích hoạt ngắt mạch và hủy bỏ tác vụ", "Tăng thời gian chờ lên vô hạn", "Gửi email cho lập trình viên"], 1,
         "Wait-For Graph và thuật toán phát hiện chu trình là giải pháp kinh điển trong khoa học máy tính để bẻ gãy bế tắc trong các hệ thống phân tán.", "Day 09 - Slide: Deadlock Detection in Multi-Agent Systems"),
        ("MCP Prompts Feature", "Tính năng 'Prompts' trong đặc tả Model Context Protocol được thiết kế để phục vụ mục đích gì?",
         ["Để người dùng gõ văn bản thông thường", "Cho phép MCP Server xuất bản các khuôn mẫu prompt được tối ưu hóa sẵn (Slash Commands / Structured Workflows) kèm theo các tham số động để người dùng kích hoạt nhanh trong ứng dụng Host", "Để đổi màu giao diện ứng dụng", "Để kiểm tra tốc độ chuột"], 1,
         "MCP Prompts chuẩn hóa các quy trình công việc phức tạp thành các lệnh tương tác tiện lợi mà người dùng có thể kích hoạt trực tiếp.", "Day 09 - Slide: MCP Prompts and Workflows"),
        ("Multi-Agent Cost Management: Early Stopping", "Chiến lược 'Cost-Aware Early Stopping' trong Multi-Agent System hoạt động theo cơ chế nào?",
         ["Ngừng toàn bộ hệ thống sau đúng 1 giây", "Gán một Ngân sách Chi phí tối đa (Max Budget in USD/Tokens) cho mỗi phiên làm việc; nếu tổng chi phí của tất cả các Agent vượt quá 80% ngân sách mà chưa hoàn thành, ép buộc chuyển sang chế độ Tóm tắt kết luận tốt nhất hiện có", "Xóa tài khoản của người dùng", "Chỉ cho phép 1 Agent chạy duy nhất"], 1,
         "Early Stopping có ý thức về chi phí ngăn chặn các kịch bản bùng nổ tài chính khi các Agent trao đổi quá nhiều bước trong các tác vụ phức tạp.", "Day 09 - Slide: Budget Control in Multi-Agent Systems"),
        ("MCP Dynamic Roots and Context Scoping", "Khái niệm 'Roots' trong giao thức MCP quy định ranh giới nào cho AI Client?",
         ["Thư mục gốc của hệ điều hành Windows", "Ranh giới các thư mục hoặc không gian làm việc (Workspace Boundaries) mà MCP Server được phép truy cập và thao tác, ngăn chặn Agent đọc các file nhạy cảm ngoài phạm vi cho phép", "Nguồn gốc xuất xứ của máy tính", "Địa chỉ nhà của người phát triển"], 1,
         "MCP Roots thiết lập hàng rào bảo mật không gian tệp tin, đảm bảo Agent chỉ được phép tương tác trong phạm vi dự án được chỉ định.", "Day 09 - Slide: MCP Roots and Security Boundaries"),
        ("Multi-Agent Simulation: Society of Mind", "Ý tưởng 'Society of Mind' của Marvin Minsky được hiện thực hóa trong Multi-Agent AI hiện đại như thế nào?",
         ["Bằng cách cấy chip vào não người", "Trí thông minh tổng quát không đến từ một khối tư duy duy nhất mà xuất hiện từ sự tương tác, cạnh tranh và hợp tác của hàng trăm tác tử đơn giản chuyên biệt cùng làm việc", "Bằng cách tắt toàn bộ máy tính", "Bằng cách vẽ sơ đồ não bộ trên giấy"], 1,
         "Kiến trúc Multi-Agent hiện thực hóa triết lý Society of Mind: xây dựng năng lực giải quyết vấn đề vượt bậc thông qua sự kết hợp của nhiều tác tử chuyên môn hóa.", "Day 09 - Slide: Theoretical Foundations: Society of Mind"),
        ("MCP Error Protocol & Codes", "Trong chuẩn JSON-RPC 2.0 của MCP, khi một Tool Call bị Server từ chối do thiếu quyền truy cập, mã lỗi chuẩn nào nên được trả về?",
         ["Trả về chuỗi văn bản 'Không được phép'", "Mã lỗi chuẩn JSON-RPC (ví dụ: `-32602 Invalid params` hoặc `-32000 Server error` kèm theo object data mô tả chi tiết quyền hạn bị từ chối)", "Mã lỗi HTTP 404", "Không trả về gì cả"], 1,
         "Tuân thủ mã lỗi chuẩn JSON-RPC giúp Client dễ dàng phân loại lỗi kỹ thuật và tự động kích hoạt luồng xử lý ngoại lệ phù hợp.", "Day 09 - Slide: JSON-RPC Error Handling in MCP"),
        ("Human-in-the-Loop in Multi-Agent Graphs", "Trong LangGraph Multi-Agent, làm thế nào để chèn một điểm dừng can thiệp của con người (Breakpoint) trước khi Agent Chuyên gia Tài chính thực hiện giao dịch chuyển tiền?",
         ["Tắt máy chủ bằng tay", "Cấu hình `interrupt_before=['transfer_funds_node']` trong StateGraph: Luồng thực thi sẽ tự động đóng băng trạng thái và chờ tín hiệu phê duyệt từ con người trước khi bước vào Node đó", "Xóa Node giao dịch khỏi đồ thị", "Tự động hoàn thành mà không cần hỏi"], 1,
         "`interrupt_before` trong LangGraph cung cấp cơ chế chặn trước tại cấp độ Node, đảm bảo các hành động trọng yếu luôn nhận được sự phê chuẩn từ con người.", "Day 09 - Slide: LangGraph Human-in-the-Loop Breakpoints")
    ]

    d09_hard = [
        ("Production Multi-Agent Orchestration Architecture", "Một hệ thống Multi-Agent Doanh nghiệp gồm 10 Agents độc lập xử lý chuỗi quy trình bảo hiểm phức tạp. Thiết kế Hạ tầng Điều phối Phân tán (Distributed Orchestrator) nào đảm bảo tính chịu lỗi (Fault Tolerance), mở rộng độc lập và bảo toàn trạng thái?",
         ["Chạy toàn bộ 10 Agents trong 1 vòng lặp for đơn luồng trên 1 máy tính duy nhất", "Triển khai Event-Driven Microservices với Message Broker (như Apache Kafka hoặc RabbitMQ) và Persistent State Store (Postgres/Redis): Mỗi Agent là một Microservice độc lập tiêu thụ message từ hàng đợi; Trạng thái toàn cục được quản lý qua Saga Orchestrator với Distributed Tracing (OpenTelemetry) xuyên suốt các Agent", "Để các Agent tự gọi API của nhau qua các địa chỉ IP động không có hàng đợi", "Lưu trạng thái vào biến toàn cục trong file Python"], 1,
         "Microservices kết hợp Message Broker và Saga Orchestration cung cấp khả năng mở rộng quy mô độc lập, cô lập lỗi và đảm bảo tính toàn vẹn trạng thái cho các hệ thống Multi-Agent phức tạp.", "Day 09 - Slide: Enterprise Distributed Multi-Agent Architecture"),
        ("MCP Cross-Server Aggregation & Gateway", "Một AI Assistant cần truy cập đồng thời 20 MCP Servers khác nhau từ nhiều nhà cung cấp. Thiết kế tầng MCP Gateway/Router nào tối ưu nhất về bảo mật và quản lý kết nối?",
         ["Để Client mở trực tiếp 20 kết nối Stdio song song trên máy người dùng", "Thiết lập một 'MCP Aggregator Gateway': Đóng vai trò là một MCP Server duy nhất đối với Client, chịu trách nhiệm tổng hợp danh mục Tools/Resources từ 20 Backend Servers, quản lý xác thực OAuth2/mTLS tập trung, và thực hiện Dynamic Routing dựa trên Tool Namespace (e.g. `github.create_issue`, `slack.send_message`)", "Cấm không cho sử dụng quá 1 MCP Server", "Bắt người dùng tự đổi cổng kết nối bằng tay"], 1,
         "MCP Gateway chuẩn hóa không gian tên (Namespacing), quản lý phiên làm việc tập trung và bảo vệ Client khỏi sự phức tạp khi kết nối với hàng chục dịch vụ phân tán.", "Day 09 - Slide: MCP Gateway & Tool Federation"),
        ("Multi-Agent Emergent Failure: Groupthink & Collusion", "Trong hệ thống Multi-Agent gồm nhiều mô hình tranh luận (Multi-Agent Debate), hiện tượng 'Groupthink / Sycophancy' (Các Agent hùa theo ý kiến sai của nhau) xảy ra do đâu và kiến trúc phòng ngừa là gì?",
         ["Do máy chủ bị nhiễm virus", "Do các Agent có xu hướng nhượng bộ và đồng thuận với luận điểm của Agent phát biểu trước đó trong ngữ cảnh chung; phòng ngừa bằng cách áp dụng 'Blind Parallel Voting': Cho các Agent suy luận độc lập không nhìn thấy câu trả lời của nhau, sau đó mới nạp vào một Arbiter Agent trung lập", "Do các Agent được viết bằng cùng một ngôn ngữ lập trình", "Không có cách nào phòng ngừa"], 1,
         "Đánh giá mù song song (Blind Parallel Evaluation) triệt tiêu sự lây lan thiên lệch (Bias Contagion) và ngăn ngừa hiện tượng hùa theo giữa các tác tử.", "Day 09 - Slide: Mitigating Groupthink & Sycophancy in MAS"),
        ("State Conflict Resolution in Concurrent Multi-Agent Systems", "Khi 2 Worker Agents thực thi song song và cùng lúc gửi bản cập nhật xung đột lên một trường dữ liệu trong Shared State, chiến lược giải quyết xung đột (Conflict Resolution) nào đảm bảo tính nhất quán dữ liệu?",
         ["Ghi đè ngẫu nhiên cái nào đến sau cùng", "Áp dụng cơ chế Khóa lạc quan (Optimistic Concurrency Control with Versioning) kết hợp Reducer chuyên biệt: Tự động phát hiện xung đột phiên bản, kích hoạt một Reconciliation Function hoặc giao quyền phân xử cho Supervisor Agent để hợp nhất dữ liệu (Semantic Merge)", "Xóa toàn bộ dữ liệu của cả 2 Agent", "Tắt hệ thống ngay lập tức"], 1,
         "Optimistic Locking và Semantic Merge Reducers đảm bảo tính toàn vẹn của trạng thái chia sẻ mà không làm nghẽn tiến trình thực thi song song của các Agent.", "Day 09 - Slide: State Reconciliation & Concurrency Control"),
        ("Dynamic Agent Spawning & Lifecycle Management", "Một tác vụ nghiên cứu thị trường quy mô lớn đòi hỏi hệ thống phải tự động sinh ra hàng chục Agent con theo nhu cầu (Dynamic Agent Spawning) và thu hồi tài nguyên sau khi xong việc. Cơ chế quản lý vòng đời (Lifecycle Engine) cần kiểm soát những gì?",
         ["Chỉ cần cấp RAM tối đa", "1. Quản lý Pool tài nguyên và giới hạn số lượng Agent tối đa (Concurrency Throttle); 2. Cơ chế Heartbeat phát hiện Agent bị treo (Stalled Agent Termination); 3. Garbage Collection tự động dọn dẹp Context và giải phóng kết nối MCP khi hoàn thành; 4. Timeout và Cost Quota trên mỗi Worker", "Không cần quản lý vòng đời", "Chờ hệ điều hành tự tắt khi tràn RAM"], 1,
         "Lifecycle Engine kiểm soát chặt chẽ việc khởi tạo, giám sát sức khỏe, cấp phát tài nguyên và dọn dẹp an toàn cho các tác tử động nhằm ngăn ngừa cạn kiệt tài nguyên hệ thống.", "Day 09 - Slide: Dynamic Agent Spawning & Resource Pooling"),
        ("MCP Transport Security over Untrusted Networks", "Khi triển khai MCP Server qua giao thức SSE/HTTP trên môi trường Internet công cộng, 3 lớp bảo mật bắt buộc phải thiết lập ở tầng Transport là gì?",
         ["Chỉ cần dùng mật khẩu 4 số", "1. Bắt buộc sử dụng TLS/HTTPS (Mã hóa đường truyền); 2. Xác thực và Phân quyền mạnh mẽ bằng OAuth 2.0 / JWT Bearer Tokens hoặc mTLS (Mutual TLS); 3. Áp dụng Rate Limiting và IP Whitelisting tại tầng API Gateway để ngăn chặn DDoS", "Không cần bảo mật vì MCP đã an toàn sẵn", "Chỉ chạy vào ban đêm"], 1,
         "Triển khai MCP qua mạng diện rộng đòi hỏi các tiêu chuẩn an toàn mạng doanh nghiệp chuẩn mực để chống nghe lén, giả mạo danh tính và tấn công từ chối dịch vụ.", "Day 09 - Slide: Securing Remote MCP Endpoints"),
        ("Multi-Agent Protocol Buffer / gRPC Optimization", "Tại sao việc chuyển đổi tầng giao tiếp giữa các Agent từ JSON-RPC qua HTTP sang Protocol Buffers qua gRPC/HTTP2 lại giúp giảm đáng kể độ trễ trong các hệ thống High-Frequency MAS?",
         ["Vì Protobuf là mã nguồn của Google", "Protobuf nén dữ liệu thành định dạng nhị phân siêu nhẹ (nhỏ hơn 70% so với JSON text), gRPC tận dụng Multiplexing trên 1 kết nối TCP duy nhất của HTTP/2 và cơ chế gán kiểu dữ liệu tĩnh nghiêm ngặt (Strict Typing) giúp giảm chi phí serialization/deserialization", "Vì Protobuf tự động tăng tốc độ xử lý của LLM", "Không có sự khác biệt nào về hiệu năng"], 1,
         "Giao thức nhị phân gRPC/Protobuf triệt tiêu độ trễ phân tích chuỗi văn bản JSON, cực kỳ tối ưu cho các luồng trao đổi dữ liệu tần suất cao giữa các cụm Agent.", "Day 09 - Slide: High-Throughput gRPC/Protobuf in Multi-Agent Networks"),
        ("Self-Organizing Agent Swarms under Partition Failures", "Trong một mạng lưới Agent Swarm phi tập trung, khi 30% số nút Agent bị ngắt kết nối mạng (Network Partition), thuật toán đồng thuận phân tán nào giúp cụm Agent còn lại tự tái cấu trúc và duy trì hoạt động?",
         ["Dừng toàn bộ hệ thống", "Thuật toán Đồng thuận Raft hoặc Gossip Protocol: Các Agent tự động phát hiện các nút bị mất liên lạc, tái bầu chọn Leader mới cho nhóm đa số (Quorum), phân bổ lại các nhiệm vụ dở dang và tiếp tục thực thi một cách tự trị", "Khởi động lại toàn bộ máy tính trên toàn cầu", "Xóa toàn bộ dữ liệu lịch sử"], 1,
         "Gossip Protocol và Quorum-based Consensus mang lại khả năng tự phục hồi và tái lập trật tự (Self-Healing) cho các mạng lưới tác tử phân tán trước sự cố đứt gãy mạng.", "Day 09 - Slide: Resilient Swarm Topologies & Partition Tolerance"),
        ("Observability in Multi-Agent Systems: Distributed Causal Tracing", "Trong một luồng xử lý gồm 15 Agent trao đổi bất đồng bộ qua message queue, làm thế nào để tái hiện chính xác 'Cây Quan hệ Nhân quả' (Causal Trace Graph) của một quyết định sai lầm?",
         ["Đọc lại file log bằng mắt thường", "Gắn kèm một Context Header bất biến chứa `trace_id`, `parent_span_id`, và `causal_event_chain` qua mọi tin nhắn trao đổi; sử dụng OpenTelemetry Tracing Engine để vẽ lại toàn bộ đồ thị Directed Acyclic Graph (DAG) của các thông điệp và quyết định theo trình tự thời gian", "Đoán mò dựa trên thời gian kết thúc", "Chỉ kiểm tra Agent cuối cùng"], 1,
         "Distributed Causal Tracing cho phép tái dựng toàn bộ chuỗi quyết định và dòng chảy thông tin qua các tác tử, là chìa khóa để gỡ lỗi các hệ thống Multi-Agent phức tạp.", "Day 09 - Slide: Causal Tracing & Telemetry in MAS"),
        ("Hierarchical Agentic Token Pruning & Distillation", "Một tác vụ nghiên cứu gồm 1 Supervisor và 5 Worker thu thập được 100,000 tokens dữ liệu thô. Kỹ thuật tóm tắt và chưng cất ngữ cảnh (Context Distillation) nào bảo đảm Supervisor đưa ra báo cáo cuối cùng chính xác mà không vượt quá 8k tokens?",
         ["Cắt bỏ ngẫu nhiên 92% số token", "Áp dụng Quy trình Chưng cất Đa tầng (Multi-tier Distillation): Mỗi Worker tự chạy một mô hình cục bộ trích xuất các Dữ kiện then chốt (Structured Key Findings) thành bản tóm tắt 1,000 tokens có schema nghiêm ngặt; Supervisor chỉ nhận 5 bản tóm tắt này (tổng cộng 5,000 tokens) để tổng hợp báo cáo", "Chuyển toàn bộ 100,000 tokens thành file ảnh nén", "Chỉ gửi kết quả của 1 Worker đầu tiên"], 1,
         "Chưng cất ngữ cảnh phân cấp biến dữ liệu thô khổng lồ thành các gói tri thức cô đọng có cấu trúc, giúp cấp quản lý ra quyết định chuẩn xác mà không bị tràn bộ nhớ.", "Day 09 - Slide: Hierarchical Context Distillation"),
        ("Agentic Safety: Jailbreak Propagation Defense", "Khi một Agent trong mạng lưới bị nhiễm mã độc qua Prompt Injection (Compromised Agent), cơ chế cách ly mạng (Agent Network Firewall / Zero Trust) nào ngăn chặn mã độc lây lan sang các Agent khác?",
         ["Tin tưởng tất cả tin nhắn nội bộ giữa các Agent", "Áp dụng Nguyên lý Zero Trust nội bộ: Mọi thông điệp trao đổi giữa các Agent đều phải đi qua Tầng Kiểm duyệt Trung gian (Inter-Agent Message Guardrail) để quét mã độc, xác thực chữ ký số của Agent gửi và chặn đứng các lệnh can thiệp quyền điều khiển", "Tắt toàn bộ hệ thống mạng", "Đổi tên các Agent bị nhiễm"], 1,
         "Zero Trust Architecture trong Multi-Agent coi mọi thông điệp nội bộ đều có thể bị xâm nhập, áp dụng kiểm duyệt chéo để cô lập sự cố tại nút bị tấn công.", "Day 09 - Slide: Zero Trust Architecture for Multi-Agent Systems"),
        ("Multi-Agent Simulation for Economic Modeling", "Khi sử dụng hệ thống Multi-Agent gồm 10,000 Agents mô phỏng hành vi thị trường tiêu dùng, kỹ thuật hạ tầng nào tối ưu hóa chi phí tính toán và bộ nhớ trên cụm máy chủ phân tán?",
         ["Mỗi Agent gọi riêng 1 API GPT-4o độc lập (tốn hàng triệu USD)", "Sử dụng Mô hình Ngôn ngữ Nhỏ được lượng tử hóa (Quantized SLMs như Llama-3.2-1B on vLLM/TensorRT) kết hợp Batching suy luận quy mô lớn, Vector State Compression và Event-driven Execution Engine (chỉ đánh thức Agent khi có sự kiện liên quan)", "Chạy mô phỏng trên một chiếc điện thoại di động", "Tự viết luật bằng các câu lệnh IF-ELSE cứng nhắc"], 1,
         "Kết hợp SLM tối ưu hóa phần cứng và kiến trúc Event-Driven giúp hiện thực hóa các mô hình mô phỏng xã hội/kinh tế quy mô hàng chục nghìn tác tử với chi phí thực tế khả thi.", "Day 09 - Slide: Large-Scale Multi-Agent Simulation Infrastructure")
    ]
    add_day("Phase 1: COMP2010", "Day 09", "Multi-Agent Systems & MCP", d09_easy, d09_med, d09_hard)

    # ==========================================
    # DAY 10: Data Pipeline & AI Observability
    # ==========================================
    d10_easy = [
        ("Data Ingestion Basics", "Data Pipeline (Đường ống dữ liệu) trong hệ thống AI chịu trách nhiệm chính cho công việc gì?",
         ["Vẽ giao diện người dùng", "Thu thập, trích xuất, làm sạch, biến đổi và nạp dữ liệu từ các nguồn khác nhau vào kho tri thức hoặc cơ sở dữ liệu phục vụ AI", "Sản xuất phần cứng máy tính", "Kiểm tra tốc độ gõ bàn phím"], 1,
         "Data Pipeline là huyết mạch của hệ thống AI, đảm bảo dữ liệu thô từ nhiều nguồn được chuẩn hóa và sẵn sàng cho các mô hình sử dụng.", "Day 10 - Slide: Data Pipeline Overview"),
        ("Data Extraction: Unstructured Text", "Thách thức lớn nhất khi trích xuất văn bản từ các tệp tin PDF phức tạp để nạp vào AI là gì?",
         ["File PDF luôn bị khóa mật khẩu", "Mất cấu trúc ngữ nghĩa (bố cục nhiều cột, bảng biểu, tiêu đề và hình ảnh bị trộn lẫn vào nhau thành chuỗi từ lộn xộn)", "File PDF không chứa chữ", "Trình duyệt web không mở được PDF"], 1,
         "Bóc tách PDF dạng văn bản thuần thường phá vỡ trật tự đọc và cấu trúc bảng biểu, đòi hỏi các công cụ Layout Analysis chuyên dụng.", "Day 10 - Slide: Unstructured Data Extraction"),
        ("Deduplication", "Kỹ thuật 'Deduplication' (Khử trùng lặp dữ liệu) trong Data Pipeline có mục đích gì?",
         ["Xóa toàn bộ dữ liệu trong cơ sở dữ liệu", "Phát hiện và loại bỏ các tài liệu hoặc đoạn văn bản trùng lặp hoàn toàn hoặc gần trùng lặp (Near-duplicates) để tiết kiệm không gian lưu trữ và tránh thiên lệch dữ liệu", "Tăng kích thước file lên gấp đôi", "Tự động dịch văn bản sang tiếng Pháp"], 1,
         "Khử trùng lặp giúp tối ưu hóa dung lượng lưu trữ, giảm chi phí tạo embedding và ngăn chặn hiện tượng lặp lại thông tin trong kết quả tìm kiếm.", "Day 10 - Slide: Data Deduplication Principles"),
        ("Data Quality Assertions", "Công cụ 'Great Expectations' trong hệ sinh thái Data Engineering được sử dụng để làm gì?",
         ["Thiết kế đồ họa website", "Khai báo và tự động kiểm tra các khẳng định chất lượng dữ liệu (Data Quality Assertions / Expectations) trên đường ống dữ liệu", "Quản lý lương nhân viên", "Gửi email chúc mừng sinh nhật"], 1,
         "Great Expectations cung cấp khung kiểm thử tự động đảm bảo dữ liệu đầu vào tuân thủ đúng schema, kiểu dữ liệu và miền giá trị quy định.", "Day 10 - Slide: Data Quality with Great Expectations"),
        ("Data Drift vs Concept Drift", "Sự khác biệt căn bản giữa 'Data Drift' và 'Concept Drift' trong vận hành hệ thống AI là gì?",
         ["Không có sự khác biệt nào", "Data Drift là sự thay đổi trong phân phối của dữ liệu đầu vào $P(X)$; Concept Drift là sự thay đổi trong mối quan hệ giữa đầu vào và đầu ra mục tiêu $P(Y|X)$", "Data Drift chỉ xảy ra vào mùa đông", "Concept Drift là lỗi phần cứng máy tính"], 1,
         "Data Drift phản ánh sự biến đổi về đặc tính dữ liệu người dùng nạp vào, trong khi Concept Drift phản ánh sự thay đổi về bản chất quy luật nghiệp vụ thực tế.", "Day 10 - Slide: Data Drift vs Concept Drift"),
        ("Data Lineage", "Khái niệm 'Data Lineage' (Nguồn gốc và Dòng chảy dữ liệu) trả lời cho câu hỏi nào?",
         ["Bao giờ thì hết giờ làm việc", "Dữ liệu này bắt nguồn từ đâu, đã trải qua những bước biến đổi nào, và đang được sử dụng bởi những mô hình/ứng dụng AI nào downstream?", "Giá cổ phiếu công ty hôm nay là bao nhiêu", "Ai là người phát minh ra máy tính"], 1,
         "Data Lineage cung cấp khả năng truy xuất nguồn gốc toàn diện, giúp định vị nhanh chóng điểm lỗi và đánh giá tác động khi một nguồn dữ liệu bị thay đổi.", "Day 10 - Slide: Data Lineage Foundations"),
        ("OpenLineage Standard", "OpenLineage là một chuẩn mở công nghiệp phục vụ cho mục đích gì?",
         ["Chuẩn hóa việc vẽ tranh bằng AI", "Chuẩn hóa việc thu thập và trao đổi siêu dữ liệu về dòng chảy dữ liệu (Data Lineage Metadata) giữa các công cụ trong pipeline như Spark, Airflow, dbt", "Chuẩn hóa kích thước màn hình máy tính", "Chuẩn hóa ngôn ngữ tiếng Anh"], 1,
         "OpenLineage cung cấp đặc tả chung để các công cụ kỹ nghệ dữ liệu tự động phát ra các sự kiện lineage một cách đồng nhất.", "Day 10 - Slide: OpenLineage Standard"),
        ("Batch vs Streaming Ingestion", "Đặc tính của phương pháp 'Batch Ingestion' (Nạp dữ liệu theo lô) là gì?",
         ["Xử lý từng ký tự một ngay khi người dùng gõ", "Gom nhóm dữ liệu và định kỳ xử lý một khối lượng lớn tại các thời điểm cố định (ví dụ: mỗi đêm hoặc mỗi giờ một lần)", "Không bao giờ lưu trữ dữ liệu", "Chỉ chạy được trên máy tính xách tay"], 1,
         "Batch Ingestion tối ưu hóa thông lượng (Throughput) cho các khối lượng dữ liệu khổng lồ không đòi hỏi tính tức thời theo thời gian thực.", "Day 10 - Slide: Batch vs Stream Processing"),
        ("Schema Validation in Pipelines", "Điều gì xảy ra nếu Data Pipeline thiếu bước 'Schema Validation' ở đầu vào?",
         ["Pipeline chạy nhanh hơn 100 lần", "Dữ liệu bị lỗi định dạng hoặc thiếu trường bắt buộc sẽ đi sâu vào hệ thống, làm sập các tiến trình tạo embedding hoặc gây lỗi ảo giác nghiêm trọng cho mô hình downstream", "Máy tính tự động tắt nguồn", "Dữ liệu tự động được sửa đúng"], 1,
         "Xác thực schema sớm (Fail Fast) ngăn chặn 'dữ liệu rác' lan truyền và phá hoại tính toàn vẹn của các tầng xử lý phía sau.", "Day 10 - Slide: Defensive Schema Validation"),
        ("ETL vs ELT", "Sự khác biệt về thứ tự các bước giữa ETL (Extract-Transform-Load) và ELT (Extract-Load-Transform) là gì?",
         ["ETL nạp dữ liệu trước rồi mới trích xuất", "ETL biến đổi dữ liệu trên máy chủ trung gian trước khi nạp vào kho; ELT nạp dữ liệu thô trực tiếp vào Data Lakehouse/Warehouse rồi mới dùng sức mạnh tính toán của kho để biến đổi", "ELT không có bước trích xuất", "Cả hai đều giống hệt nhau"], 1,
         "ELT tận dụng năng lực xử lý phân tán cực mạnh của các nền tảng đám mây hiện đại (BigQuery, Snowflake, Spark) để biến đổi dữ liệu trực tiếp tại đích.", "Day 10 - Slide: Modern ETL vs ELT Paradigms"),
        ("Dead Letter Queue (DLQ)", "Trong Data Pipeline, 'Dead Letter Queue' (Hàng đợi thư chết) được sử dụng để làm gì?",
         ["Để xóa vĩnh viễn các email cũ", "Lưu trữ riêng biệt các bản ghi dữ liệu bị lỗi hoặc không thể xử lý được, giúp pipeline chính không bị nghẽn và cho phép kỹ sư kiểm tra, sửa lỗi sau đó", "Để tăng tốc độ đường truyền internet", "Để lưu mật khẩu người dùng"], 1,
         "DLQ là chốt chặn an toàn đảm bảo tính liên tục của đường ống dữ liệu, cô lập các bản ghi lỗi để phục vụ công tác điều tra mà không làm gián đoạn toàn bộ hệ thống.", "Day 10 - Slide: Dead Letter Queue (DLQ) Pattern"),
        ("Data Pipeline Telemetry", "Chỉ số 'Pipeline Freshness' (Độ tươi mới của dữ liệu) đo lường điều gì?",
         ["Mùi hương của phòng máy chủ", "Khoảng thời gian chênh lệch giữa thời điểm dữ liệu được sinh ra ở nguồn thực tế và thời điểm dữ liệu đó sẵn sàng cho AI truy vấn trong cơ sở dữ liệu", "Nhiệt độ của ổ cứng lưu trữ", "Số lượng file mới tạo trong ngày"], 1,
         "Freshness đo lường độ trễ cập nhật tri thức của hệ thống, yếu tố sống còn cho các bài toán thời gian thực như phát hiện gian lận tài chính.", "Day 10 - Slide: Data Observability Pillars: Freshness"),
        ("Airflow DAGs", "Trong công cụ điều phối Apache Airflow, 'DAG' là từ viết tắt của khái niệm nào?",
         ["Direct Action Group", "Directed Acyclic Graph (Đồ thị có hướng không chu trình) dùng để biểu diễn các tác vụ và quan hệ phụ thuộc giữa chúng trong pipeline", "Data Automatic Generator", "Digital Audio Grid"], 1,
         "Airflow mô hình hóa quy trình xử lý dữ liệu dưới dạng DAG, đảm bảo các tác vụ được thực thi đúng thứ tự logic mà không bị vòng lặp vô hạn.", "Day 10 - Slide: Airflow DAG Fundamentals"),
        ("Data Anonymization: PII Masking", "Kỹ thuật 'PII Masking' (Che giấu thông tin định danh cá nhân) trong Data Pipeline có vai trò gì?",
         ["Tăng tốc độ mạng", "Tự động phát hiện và thay thế các thông tin nhạy cảm (Số CMND/CCCD, Số điện thoại, Email, Thẻ tín dụng) bằng các ký tự ẩn hoặc token giả định trước khi nạp vào AI", "Xóa toàn bộ nội dung tài liệu", "Chuyển dữ liệu thành file âm thanh"], 1,
         "PII Masking là yêu cầu bắt buộc để tuân thủ các quy định bảo vệ dữ liệu cá nhân (GDPR, Luật bảo vệ dữ liệu cá nhân) và ngăn ngừa rò rỉ thông tin nhạy cảm.", "Day 10 - Slide: PII Redaction & Data Masking"),
        ("Data Pipeline Alerting", "Khi một tác vụ nạp dữ liệu bị thất bại 3 lần liên tiếp, hệ thống điều phối pipeline nên làm gì ngay lập tức?",
         ["Tự động tắt toàn bộ máy tính công ty", "Gửi cảnh báo tức thì (Alert Notification qua Slack, PagerDuty, Email) tới đội ngũ On-call kèm theo log lỗi chi tiết và trạng thái của DAG", "Giấu nhẹm lỗi và coi như đã hoàn thành", "Xóa toàn bộ database"], 1,
         "Cảnh báo tự động kèm ngữ cảnh sự cố giúp đội ngũ vận hành phản ứng kịp thời trước khi sự cố dữ liệu ảnh hưởng tới người dùng cuối.", "Day 10 - Slide: Automated Pipeline Alerting")
    ]

    d10_med = [
        ("MinHash LSH Deduplication", "Thuật toán MinHash kết hợp Locality-Sensitive Hashing (LSH) giải quyết bài toán khử trùng lặp xấp xỉ (Near-deduplication) cho hàng triệu văn bản với độ phức tạp tính toán như thế nào?",
         ["Độ phức tạp $O(N^2)$ so sánh từng cặp văn bản", "Độ phức tạp tuyến tính xấp xỉ $O(N)$ bằng cách băm tập n-grams (Shingles) thành các MinHash signatures và nhóm các văn bản có chữ ký tương đồng vào cùng bucket để so khớp nhanh", "Độ phức tạp $O(1)$ tức thời", "Không thể chạy được trên máy tính"], 1,
         "MinHash LSH giảm số lượng phép so sánh từ hàng nghìn tỷ cặp xuống các bucket lân cận, cho phép khử trùng lặp quy mô hàng chục triệu văn bản một cách hiệu quả.", "Day 10 - Slide: MinHash LSH for Near-Deduplication"),
        ("Five Pillars of Data Observability", "Năm trụ cột cốt lõi của 'Data Observability' trong kỹ nghệ dữ liệu hiện đại bao gồm những yếu tố nào?",
         ["Màn hình, Bàn phím, Chuột, Tai nghe, Vỏ máy", "1. Freshness (Độ tươi), 2. Volume (Khối lượng/Số lượng bản ghi), 3. Distribution (Phân phối dữ liệu/Giá trị null/Khoảng giá trị), 4. Schema (Tính toàn vẹn cấu trúc), 5. Lineage (Dòng chảy nguồn gốc)", "HTML, CSS, JS, Python, SQL", "Tốc độ quạt, Nhiệt độ CPU, Dung lượng RAM, Băng thông mạng, Nguồn điện"], 1,
         "Năm trụ cột quan sát dữ liệu cung cấp bức tranh toàn cảnh về sức khỏe và độ tin cậy của toàn bộ hạ tầng dữ liệu doanh nghiệp.", "Day 10 - Slide: Five Pillars of Data Observability"),
        ("Data Drift Detection: PSI & KS-Test", "Chỉ số PSI (Population Stability Index) và Kiểm định Kolmogorov-Smirnov (KS-Test) được sử dụng để phát hiện điều gì trong Data Pipeline?",
         ["Phát hiện virus máy tính", "Đo lường mức độ trôi lệch phân phối thống kê (Statistical Distribution Shift) của các đặc trưng dữ liệu đầu vào giữa tập huấn luyện ban đầu và dữ liệu thực tế đang chạy trên Production", "Kiểm tra tốc độ gõ bàn phím của người dùng", "Đo lường điện năng tiêu thụ"], 1,
         "PSI và KS-Test là các công cụ thống kê toán học tiêu chuẩn để phát hiện sớm hiện tượng suy thoái dữ liệu trước khi mô hình AI bị giảm sút độ chính xác.", "Day 10 - Slide: Statistical Drift Detection Metrics"),
        ("Change Data Capture (CDC)", "Kỹ thuật 'Change Data Capture' (CDC với công cụ như Debezium/Kafka Connect) đồng bộ dữ liệu vào Vector DB theo cơ chế nào?",
         ["Quét toàn bộ bảng database mỗi 5 phút một lần", "Đọc trực tiếp Nhật ký Giao dịch (Transaction Log / Binlog / WAL) của cơ sở dữ liệu quan hệ và phát các sự kiện Insert/Update/Delete theo thời gian thực để cập nhật ngay vào Vector Index", "Chờ người dùng gửi email thông báo thay đổi", "Chỉ đồng bộ 1 lần duy nhất trong năm"], 1,
         "CDC nắm bắt các biến động dữ liệu ở cấp độ transaction log với độ trễ tính bằng mili-giây mà không gây tải phụ cho cơ sở dữ liệu nguồn.", "Day 10 - Slide: Change Data Capture (CDC) Architecture"),
        ("Idempotency in Data Pipelines", "Một bước xử lý dữ liệu được coi là 'Idempotent' (Có tính chất lũy đẳng) khi nó thỏa mãn điều kiện nào?",
         ["Khi nó chỉ chạy được đúng 1 lần duy nhất trong đời", "Khi việc thực thi bước đó nhiều lần trên cùng một tập dữ liệu đầu vào luôn tạo ra trạng thái kết quả đầu ra giống hệt như thực thi đúng 1 lần (ví dụ: dùng câu lệnh UPSERT thay vì INSERT thuần)", "Khi nó chạy với tốc độ ánh sáng", "Khi nó tự động xóa code sau khi chạy"], 1,
         "Tính chất lũy đẳng là nguyên lý sống còn của Data Engineering, cho phép tự động Retry an toàn khi gặp sự cố mạng mà không làm nhân bản dữ liệu.", "Day 10 - Slide: Idempotent Pipeline Design"),
        ("PDF Layout Analysis: Vision Models vs OCR", "Khi xử lý tài liệu PDF có định dạng phức tạp (như Báo cáo y khoa có nhiều cột và biểu đồ), tại sao việc kết hợp 'Layout-Aware Vision Models' (như LayoutLM hoặc Vision Document Parsers) lại vượt trội hơn OCR truyền thống?",
         ["Vì Vision Models không tốn tiền", "Vì OCR truyền thống chỉ đọc ký tự theo thứ tự tọa độ từ trái sang phải làm lẫn lộn các cột; Vision Models nhận thức được cấu trúc thị giác (Bounding Boxes, Quan hệ khối, Tiêu đề con) để nhóm các đoạn văn theo đúng trật tự đọc tự nhiên", "Vì OCR truyền thống chỉ đọc được tiếng Anh", "Vì Vision Models chạy trên điện thoại"], 1,
         "Mô hình thị giác bố cục kết hợp cả thông tin hình ảnh thị giác và văn bản giúp tái cấu trúc chính xác dòng chảy ngữ nghĩa của tài liệu phức tạp.", "Day 10 - Slide: Layout-Aware Document Parsing"),
        ("Pipeline Backpressure Handling", "Hiện tượng 'Backpressure' xảy ra trong Streaming Pipeline khi nào và cơ chế giải quyết là gì?",
         ["Khi máy tính bị quá nhiệt", "Xảy ra khi tốc độ nguồn phát sinh dữ liệu (Producer) nhanh hơn nhiều so với tốc độ xử lý của tầng Embedding/LLM (Consumer); giải pháp là sử dụng Message Queue có đệm (Kafka Buffering) kết hợp cơ chế Flow Control và Auto-scaling Consumer instances", "Khi dây mạng bị đứt", "Khi người dùng tắt trình duyệt"], 1,
         "Backpressure handling điều tiết luồng dữ liệu một cách nhịp nhàng, ngăn chặn hiện tượng tràn bộ nhớ (OOM) tại các nút tiêu thụ dữ liệu.", "Day 10 - Slide: Backpressure & Flow Control in Streaming"),
        ("Data Quality Firewall: Circuit Breakers", "Một 'Data Quality Circuit Breaker' trong pipeline tự động ngắt luồng xử lý khi phát hiện điều kiện nào?",
         ["Khi nhiệt độ phòng máy chủ tăng", "Khi tỉ lệ bản ghi bị lỗi (Null values, Invalid format, Anomalous volume drop) vượt quá một ngưỡng an toàn định trước (ví dụ: > 5% lỗi), ngăn chặn việc nạp dữ liệu bẩn vào Knowledge Base", "Khi hết giờ làm việc", "Khi lập trình viên commit code mới"], 1,
         "Data Circuit Breaker hoạt động như một cầu dao an toàn, chủ động dừng nạp dữ liệu khi chất lượng bị suy thoái bất thường để bảo vệ hệ thống AI downstream.", "Day 10 - Slide: Data Quality Circuit Breakers"),
        ("OpenLineage Event Structure", "Một sự kiện Lineage chuẩn trong OpenLineage bao gồm 3 thực thể cốt lõi nào?",
         ["User, Password, Token", "Job (Tiến trình/Tác vụ thực thi), Dataset (Tập dữ liệu đầu vào Inputs và đầu ra Outputs), và Run (Phiên thực thi cụ thể với trạng thái START/COMPLETE/FAIL)", "File, Folder, Drive", "Host, Port, IP"], 1,
         "Mô hình dữ liệu OpenLineage xoay quanh 3 khái niệm Jobs, Datasets và Runs, cung cấp cấu trúc chuẩn mực để lập bản đồ dòng chảy dữ liệu.", "Day 10 - Slide: OpenLineage Data Model"),
        ("Vector DB Data Ingestion Partitioning", "Khi nạp 100 triệu vector vào Vector Database, tại sao việc nạp theo từng 'Partition/Batch' có sắp xếp (Sorted/Clustered Ingestion) lại giúp tăng tốc độ lập chỉ mục HNSW gấp 3 lần?",
         ["Vì nó làm máy tính chạy êm hơn", "Vì việc nạp các vector có vị trí ngữ nghĩa gần nhau vào cùng một thời điểm tối ưu hóa bộ nhớ đệm CPU/RAM (Locality of Reference), giảm thiểu việc hoán đổi trang nhớ (Cache Misses) khi xây dựng đồ thị láng giềng", "Vì nó tự động tắt các tiến trình khác", "Vì nó làm giảm số chiều của vector"], 1,
         "Tính cục bộ tham chiếu (Cache Locality) giúp tăng tốc đáng kể quá trình tính toán và liên kết các nút trong cấu trúc đồ thị không gian nhiều chiều.", "Day 10 - Slide: High-Performance Vector Ingestion"),
        ("Automated Data Pipeline Healing", "Cơ chế 'Self-Healing Data Pipeline' xử lý tự động sự cố mất kết nối cơ sở dữ liệu tạm thời như thế nào?",
         ["Xóa toàn bộ database nguồn", "Áp dụng chiến lược Retry với Exponential Backoff và Jitter, nếu thất bại quá số lần quy định thì chuyển hướng bản ghi vào Dead Letter Queue (DLQ), gửi cảnh báo và tiếp tục xử lý các bản ghi tiếp theo mà không dừng toàn bộ hệ thống", "Khởi động lại toàn bộ hệ điều hành", "Bỏ qua không lưu trữ dữ liệu"], 1,
         "Tự phục hồi lỗi mạng tạm thời và cách ly bản ghi lỗi vào DLQ đảm bảo pipeline vận hành bền bỉ 24/7 mà không cần sự can thiệp thủ công liên tục của con người.", "Day 10 - Slide: Self-Healing Pipeline Design"),
        ("Schema Evolution in Data Lakes", "Khi một trường dữ liệu trong bảng nguồn thay đổi kiểu dữ liệu (ví dụ: từ `int` sang `string`), kỹ thuật 'Schema Evolution' trong Delta Lake / Apache Iceberg xử lý như thế nào?",
         ["Báo lỗi sập toàn bộ hệ thống", "Cho phép mở rộng hoặc biến đổi schema của bảng dữ liệu một cách an toàn mà không làm hỏng các bản ghi lịch sử cũ, hỗ trợ đọc tương thích ngược và tương thích xuôi (Backward/Forward Compatibility)", "Tự động xóa toàn bộ bảng dữ liệu cũ", "Bắt buộc phải cài lại hệ điều hành"], 1,
         "Schema Evolution cho phép cấu trúc dữ liệu tiến hóa linh hoạt theo yêu cầu nghiệp vụ mà không làm gián đoạn các ứng dụng đang khai thác dữ liệu lịch sử.", "Day 10 - Slide: Schema Evolution in Modern Data Lakes"),
        ("Data Freshness SLA Monitoring", "Để đảm bảo SLA Độ tươi mới của dữ liệu (Data Freshness < 15 phút) cho Agent hỗ trợ khách hàng, hệ thống giám sát cần theo dõi metric nào?",
         ["Thời gian bật máy tính", "Chỉ số `max(current_timestamp - record_updated_at)` trên tập dữ liệu đã index trong Vector DB; nếu độ trễ vượt quá 15 phút, kích hoạt cảnh báo Freshness SLA Breach", "Số lượng ký tự trong file log", "Tốc độ quạt tản nhiệt"], 1,
         "Theo dõi thời gian chênh lệch của bản ghi mới nhất so với thời gian thực giúp phát hiện ngay các sự cố tắc nghẽn trong đường ống nạp dữ liệu.", "Day 10 - Slide: Freshness SLA Tracking"),
        ("Great Expectations: Profiling vs Validation", "Trong thư viện Great Expectations, sự khác biệt giữa 'Data Profiling' và 'Data Validation' là gì?",
         ["Không có sự khác biệt nào", "Data Profiling tự động phân tích dữ liệu hiện có để gợi ý bộ quy tắc chuẩn (Expectation Suite); Data Validation chạy bộ quy tắc đó trên các lô dữ liệu mới để kiểm tra xem có đạt chuẩn hay không", "Profiling dùng để vẽ biểu đồ; Validation dùng để xóa file", "Profiling chỉ chạy được trên môi trường Windows"], 1,
         "Profiling hỗ trợ tự động khám phá các đặc trưng dữ liệu để sinh ra bộ luật kiểm thử; Validation là bước thực thi kiểm tra chất lượng trên pipeline thực tế.", "Day 10 - Slide: Profiling vs Validation Workflows"),
        ("Synthetic Data for Pipeline Stress Testing", "Khi chuẩn bị cho sự kiện siêu khuyến mãi (Black Friday), phương pháp kiểm thử tải đường ống dữ liệu (Pipeline Stress Testing) chuẩn mực là gì?",
         ["Chờ đến ngày Black Friday rồi mới xem hệ thống có sập không", "Sử dụng các công cụ sinh dữ liệu giả lập (Synthetic Data Generators) để bơm lưu lượng dữ liệu gấp 10 lần tải thông thường vào đường ống, đo lường điểm gãy (Breaking Point), độ trễ hàng đợi và khả năng tự co giãn của cụm máy chủ", "Tắt toàn bộ hệ thống để bảo trì", "Thuê 100 nhân viên ngồi nhập liệu bằng tay"], 1,
         "Stress Testing với dữ liệu giả lập quy mô lớn giúp xác định chính xác các nút thắt cổ chai hạ tầng và chuẩn bị năng lực dự phòng trước các đợt bùng nổ lưu lượng.", "Day 10 - Slide: Pipeline Stress Testing & Synthetic Data"),
        ("Data Lineage Impact Analysis", "Khi một bảng dữ liệu nguồn `customers_raw` chuẩn bị bị xóa một cột, tính năng 'Impact Analysis' của Data Lineage giúp kỹ sư biết được điều gì?",
         ["Biết được thời tiết ngày mai", "Danh sách chi tiết toàn bộ các Data Pipelines, Vector Collections, Agent Prompts và Báo cáo Dashboard nào downstream sẽ bị gãy hoặc bị ảnh hưởng nếu cột đó bị xóa", "Biết được giá tiền điện tiêu thụ", "Không cung cấp thông tin gì hữu ích"], 1,
         "Impact Analysis trên đồ thị Lineage cho phép đánh giá chính xác phạm vi ảnh hưởng trước khi thực hiện các thay đổi schema, ngăn ngừa các sự cố gãy vỡ dây chuyền.", "Day 10 - Slide: Automated Impact Analysis"),
        ("Metadata-Driven Pipeline Orchestration", "Mô hình 'Metadata-Driven Pipeline' (Đường ống điều phối theo siêu dữ liệu) hoạt động khác với Pipeline viết code cứng ở điểm nào?",
         ["Không sử dụng máy tính", "Toàn bộ cấu hình nguồn dữ liệu, quy tắc biến đổi, lịch chạy và đích nạp được lưu trữ dưới dạng Metadata/Config (YAML/JSON/Database); một Engine duy nhất đọc config để tự động sinh và thực thi các luồng xử lý tương ứng", "Chạy chậm hơn 1,000 lần", "Chỉ chạy được trên điện thoại"], 1,
         "Metadata-driven architecture cho phép mở rộng thêm hàng trăm nguồn dữ liệu mới chỉ bằng việc thêm file cấu hình mà không cần viết lại mã nguồn pipeline.", "Day 10 - Slide: Metadata-Driven Data Pipelines"),
        ("Data Anomaly Detection with Machine Learning", "Các nền tảng Data Observability hiện đại (như Monte Carlo, Datafold) sử dụng Machine Learning để phát hiện bất thường dữ liệu theo cơ chế nào?",
         ["Bắt người dùng tự viết hàng nghìn câu lệnh IF-ELSE", "Tự động học phân phối và quy luật theo chu kỳ thời gian (Seasonal Patterns) của khối lượng dữ liệu và tỉ lệ null; tự động kích hoạt cảnh báo khi một chỉ số vượt ra ngoài khoảng dự báo tin cậy (Confidence Bands) mà không cần cấu hình ngưỡng thủ công", "Tự động xóa các file có dung lượng lớn", "Gửi tin nhắn quảng cáo cho khách hàng"], 1,
         "Anomaly Detection bằng ML tự động thích ứng với tính chu kỳ của dữ liệu kinh doanh (ví dụ: cuối tuần lưu lượng giảm), loại bỏ hiện tượng cảnh báo rác (Alert Fatigue).", "Day 10 - Slide: ML-Powered Data Anomaly Detection")
    ]

    d10_hard = [
        ("Enterprise Real-time Data Observability Architecture", "Thiết kế một Hệ thống Data Observability Toàn diện phục vụ 500 Data Pipelines và Cụm Vector DB của một tập đoàn tài chính. Kiến trúc end-to-end nào đáp ứng chuẩn Zero Data Downtime?",
         ["Để các kỹ sư tự kiểm tra ngẫu nhiên bằng câu lệnh SQL thủ công mỗi tuần", "Triển khai Kiến trúc Phân tầng Hiện đại: 1. Thu thập OpenLineage Events và Metrics từ Airflow/Spark/Kafka nạp vào Marquez/DataHub; 2. Tích hợp Great Expectations & Soda Core chạy Validation tại mọi cổng giao nhận dữ liệu; 3. Engine Phát hiện Bất thường thời gian thực (ML Anomaly Detector) theo dõi 5 trụ cột; 4. Automated Circuit Breakers tự động cô lập dữ liệu lỗi và gửi Incident Ticket qua PagerDuty/Jira", "Chỉ mua thêm ổ cứng lưu trữ mà không cần giám sát", "Tắt toàn bộ hệ thống kiểm thử tự động để tiết kiệm CPU"], 1,
         "Kiến trúc Observability toàn diện kết hợp giữa chuẩn OpenLineage, kiểm thử tự động tại các cổng, phát hiện bất thường bằng ML và ngắt mạch tự động đảm bảo kiểm soát tuyệt đối chất lượng dữ liệu doanh nghiệp.", "Day 10 - Slide: Enterprise Data Observability Architecture"),
        ("Large-Scale Deduplication with MinHash & GPU Acceleration", "Cần khử trùng lặp cho 200 triệu văn bản báo chí (hơn 1TB text) trong vòng 2 giờ trước khi tạo embedding cho LLM. Kiến trúc xử lý phân tán nào sau đây đạt hiệu năng tối ưu nhất?",
         ["Chạy vòng lặp so sánh 2 văn bản trên 1 máy tính CPU thông thường", "Sử dụng Apache Spark phân tán kết hợp GPU-accelerated MinHash/LSH (như cuML / RAPIDS): Băm văn bản thành k-shingles trên GPU -> Sinh MinHash Signatures song song -> LSH Banding phân cụm vào các Buckets phân tán -> Lọc các cặp ứng viên (Jaccard > 0.85) và loại bỏ trùng lặp trong bộ nhớ phân tán", "Gửi toàn bộ 200 triệu văn bản qua API của OpenAI để hỏi xem có trùng không", "In văn bản ra giấy và thuê 10,000 người đọc kiểm tra"], 1,
         "Tận dụng sức mạnh tính toán song song của cụm Spark và tăng tốc GPU với RAPIDS cho phép xử lý bài toán khử trùng lặp quy mô hàng trăm triệu bản ghi trong thời gian kỷ lục.", "Day 10 - Slide: Distributed GPU-Accelerated Deduplication"),
        ("Real-time CDC Streaming Pipeline with Vector Index Sync", "Một hệ sinh thái E-commerce có 10 triệu sản phẩm với hàng nghìn thay đổi về giá, tồn kho và mô tả mỗi phút. Thiết kế Kiến trúc Đồng bộ Thời gian thực (Sub-second Vector Synchronization) nào đảm bảo tính nhất quán dữ liệu cao nhất?",
         ["Chạy lệnh Re-embed toàn bộ 10 triệu sản phẩm vào cuối mỗi ngày", "Triển khai Change Data Capture (Debezium trên PostgreSQL WAL) phát sự kiện vào Kafka Topic -> Flink Stream Processor lọc và làm giàu dữ liệu -> Async Batching Embedding Service (với Semantic Cache & Deduplication) -> Ghi trực tiếp vào Real-time Memory Index của Qdrant/Milvus với Idempotent Upsert", "Yêu cầu nhân viên nhập liệu tự cập nhật vào Vector DB", "Tắt tính năng cập nhật sản phẩm trong giờ hành chính"], 1,
         "Kiến trúc CDC kết hợp Kafka, Flink và Streaming Vector Upsert đảm bảo mọi thay đổi sản phẩm được phản ánh vào không gian tìm kiếm của AI trong thời gian dưới 1 giây mà không làm gián đoạn dịch vụ.", "Day 10 - Slide: Real-time CDC & Vector Synchronization Architecture"),
        ("Statistical Concept Drift Mitigation in Production LLM Pipelines", "Hệ thống AI phân loại văn bản pháp lý bị suy thoái hiệu năng sau khi một đạo luật mới được ban hành (Concept Drift). Quy trình Tự động Nhận diện và Tái thích ứng (Automated Drift Remediation Workflow) gồm những bước nào?",
         ["Khởi động lại máy tính và hy vọng mô hình sẽ tự hiểu luật mới", "1. Drift Detector phát hiện sự gia tăng đột biến của Embedding Distance và suy giảm Logprobs trên các văn bản mới; 2. Hệ thống tự động kích hoạt Triage Queue gửi các mẫu lệch lạc cho Chuyên gia pháp lý gán nhãn; 3. Bổ sung dữ liệu mới vào Golden Dataset; 4. Tự động kích hoạt Pipeline Tinh chỉnh mô hình (Fine-Tuning / Few-shot Exemplar Update) và chạy lại Eval Suite trước khi phát hành phiên bản mới", "Xóa toàn bộ luật mới khỏi hệ thống", "Đổ lỗi cho cơ quan ban hành luật"], 1,
         "Quy trình khép kín phát hiện trôi lệch -> cách ly mẫu lỗi -> con người gán nhãn -> tự động cập nhật và kiểm thử hồi quy là giải pháp chuẩn mực để duy trì độ sắc bén của AI trước các biến động nghiệp vụ thực tế.", "Day 10 - Slide: Automated Concept Drift Remediation Pipeline"),
        ("Document Layout & Table Extraction Engine for Complex Scanned Docs", "Xây dựng Pipeline trích xuất tự động cho 10 triệu tài liệu y tế quét dạng scan (chữ viết tay, bảng biểu méo mó, dấu mộc đè chữ). Thiết kế Tầng Xử lý Đa mô hình (Multi-Engine Document Pipeline) nào đạt độ chính xác cao nhất?",
         ["Dùng thư viện `pypdf` đọc text thông thường", "Pipeline 4 giai đoạn: 1. Computer Vision Pre-processing (Khử nhiễu, căn chỉnh góc xoay, phân tách lớp dấu mộc); 2. Layout Detection (YOLO-Document / LayoutLM) phân vùng tiêu đề, văn bản, bảng biểu; 3. Chuyên môn hóa OCR (TrOCR cho chữ viết tay, Table-Transformer cho bảng biểu); 4. LLM Reconstruction ghép nối các khối thành cấu trúc Markdown ngữ nghĩa hoàn chỉnh", "Chụp ảnh màn hình rồi gửi qua email", "Chỉ đọc trang đầu tiên của mỗi tài liệu"], 1,
         "Kết hợp xử lý thị giác chuyên sâu, nhận diện bố cục và các mô hình OCR chuyên biệt cho từng loại nội dung giúp phục hồi trọn vẹn dữ liệu từ các nguồn tài liệu scan phức tạp nhất.", "Day 10 - Slide: Advanced Multi-Modal Document Extraction Pipelines"),
        ("Fault-Tolerant Distributed Pipeline with Exact-Once Processing", "Trong một đường ống xử lý dữ liệu tài chính phục vụ AI giao dịch, làm thế nào để đảm bảo tính chất 'Chính xác một lần' (Exactly-Once Semantics - EOS) từ Kafka đến Vector Database ngay cả khi các node máy chủ bị crash giữa chừng?",
         ["Chỉ cần hy vọng mạng không bao giờ bị lỗi", "Kết hợp Kafka Transactional Producer (Ghi thông điệp nguyên tử) với Flink Two-Phase Commit Sink và Cơ chế Lưu trữ Idempotent trên Vector DB (sử dụng Document Hash làm Unique ID cho thao tác Upsert), đảm bảo trạng thái không bị mất mát hay nhân bản khi xảy ra phục hồi từ Checkpoint", "Tắt toàn bộ cơ chế lưu trữ phân tán", "Gửi mỗi giao dịch 3 lần để phòng hờ"], 1,
         "Two-Phase Commit kết hợp Idempotent Upsert trên khóa băm nội dung đảm bảo tính toàn vẹn giao dịch tuyệt đối (Exactly-Once) xuyên suốt toàn bộ đường ống phân tán.", "Day 10 - Slide: Exactly-Once Processing in AI Data Pipelines"),
        ("Data Quality Anomaly Alert Fatigue Mitigation", "Hệ thống giám sát dữ liệu gửi 500 cảnh báo mỗi ngày khiến đội ngũ kỹ sư bị 'Hội chứng Mệt mỏi vì Cảnh báo' (Alert Fatigue) và bỏ qua các sự cố thực sự nghiêm trọng. Chiến lược Tinh gọn và Gom cụm Cảnh báo (Alert Correlation & Deduplication) cần triển khai như thế nào?",
         ["Tắt toàn bộ hệ thống cảnh báo", "Triển khai Tầng Tương quan Thông minh (Alert Correlation Engine): Gom cụm các cảnh báo có cùng nguyên nhân gốc rễ dựa trên Đồ thị Lineage (Root Cause Grouping), phân cấp mức độ nghiêm trọng (SEV1-SEV3) dựa trên mức độ ảnh hưởng nghiệp vụ, và chỉ phát âm thanh khẩn cấp cho các sự cố làm gián đoạn luồng phục vụ chính", "Chỉ gửi cảnh báo vào ngày thứ sáu", "Tự động xóa cảnh báo sau 1 giây"], 1,
         "Gom cụm cảnh báo theo đồ thị nguồn gốc (Lineage-based Correlation) giúp chuyển đổi hàng trăm tín hiệu nhiễu thành một thông điệp sự cố duy nhất chỉ rõ nguyên nhân gốc rễ cho đội ngũ kỹ sư.", "Day 10 - Slide: Alert Fatigue & Root Cause Correlation"),
        ("Automated PII De-identification with Reversible Tokenization", "Trong một hệ thống RAG Y tế, làm thế nào để ẩn danh thông tin bệnh nhân (PII De-identification) khi nạp vào Vector DB nhưng vẫn cho phép bác sĩ có thẩm quyền tra cứu ngược lại danh tính gốc khi cần thiết?",
         ["Xóa vĩnh viễn tên bệnh nhân và không lưu lại bất kỳ dấu vết nào", "Sử dụng Cơ chế Mã hóa Thay thế Có thể Hoàn tác (Reversible Pseudonymization / Format-Preserving Encryption with Key Vault): Thay thế PII bằng các Token định danh duy nhất (Pseudonyms) và lưu bảng ánh xạ giải mã trong một Cơ sở dữ liệu Bảo mật chuyên biệt (HSM/Vault) với quyền truy cập nghiêm ngặt và Audit Log chi tiết", "Lưu tên bệnh nhân trong file text công khai", "Dùng mật khẩu đơn giản '123456' để khóa dữ liệu"], 1,
         "Pseudonymization có thể đảo ngược bảo vệ dữ liệu trong không gian phân tích AI nhưng vẫn đảm bảo tính khả dụng lâm sàng khi các chuyên gia y tế được ủy quyền cần truy xuất hồ sơ gốc.", "Day 10 - Slide: Reversible De-identification & Compliance Architecture"),
        ("High-Throughput Vector DB Backpressure & Rate-Adaptive Ingestion", "Khi một batch 50 triệu vector được đẩy vào Vector DB làm CPU máy chủ nhảy lên 100% và gây timeout cho các truy vấn tìm kiếm của người dùng trực tuyến, kiến trúc Điều tiết Tải Động (Dynamic Adaptive Rate Ingestion) nào bảo toàn tính sẵn sàng của dịch vụ?",
         ["Ngắt kết nối của toàn bộ người dùng đang online", "Triển khai Bộ điều tiết thích ứng (Adaptive Ingestion Controller): Tự động giám sát độ trễ p99 của các truy vấn Online Search; nếu độ trễ vượt ngưỡng 50ms, bộ điều tiết tự động giảm tốc độ nạp dữ liệu nền (Throttle Ingestion Rate) và phân bổ lại tài nguyên CPU/GPU cho luồng Online phục vụ người dùng", "Xóa toàn bộ 50 triệu vector", "Khởi động lại cụm máy chủ mỗi 2 phút"], 1,
         "Hệ thống điều tiết thích ứng ưu tiên tài nguyên cho lưu lượng người dùng thời gian thực (User-facing Traffic), duy trì SLA ổn định trong khi vẫn hoàn thành tác vụ nạp dữ liệu nền.", "Day 10 - Slide: Adaptive Ingestion & Workload Isolation"),
        ("Data Pipeline Schema Evolution with Contract Testing", "Khi đội ngũ phụ trách Database nguồn thay đổi định dạng dữ liệu khách hàng làm gãy toàn bộ Pipeline AI downstream mà không báo trước, phương pháp 'Data Contract Testing' thiết lập kỷ luật kỹ thuật như thế nào?",
         ["Cấm đội ngũ database không được sửa đổi hệ thống", "Thiết lập Hợp đồng Dữ liệu (Data Contracts) dưới dạng Schema Specification được kiểm soát phiên bản bằng Git; tích hợp Contract Verification vào quy trình CI/CD của database nguồn: Bất kỳ thay đổi schema nào phá vỡ hợp đồng với AI downstream sẽ bị chặn merge tự động tại Pull Request", "Gửi email khiếu nại sau khi hệ thống đã sập", "Chấp nhận việc hệ thống bị sập định kỳ"], 1,
         "Data Contracts biến mối quan hệ giữa nhà cung cấp dữ liệu và người tiêu thụ AI thành cam kết kỹ thuật được thực thi tự động qua CI/CD, triệt tiêu nguy cơ gãy vỡ âm thầm.", "Day 10 - Slide: Data Contracts & Automated CI/CD Enforcement"),
        ("Zero-Downtime Data Pipeline Blue-Green Deployment", "Làm thế nào để nâng cấp một Data Pipeline đang xử lý 10,000 sự kiện/giây lên phiên bản logic mới mà không làm mất mát bất kỳ sự kiện nào và không gây gián đoạn dịch vụ RAG?",
         ["Tắt pipeline cũ, chờ 2 tiếng rồi bật pipeline mới", "Triển khai Kiến trúc Blue-Green Pipeline: Chạy song song Pipeline Mới (Green) bên cạnh Pipeline Cũ (Blue) cùng đọc chung dữ liệu từ Kafka nhưng ghi vào Shard Vector DB mới; sau khi kiểm tra chất lượng dữ liệu trên Green đạt chuẩn, chuyển hướng toàn bộ lưu lượng truy vấn sang Shard mới chỉ bằng 1 thao tác chuyển mạch DNS/Router", "Khởi động lại toàn bộ trung tâm dữ liệu", "Chỉ nâng cấp vào dịp Tết"], 1,
         "Blue-Green Deployment cho Data Pipelines đảm bảo tính liên tục tuyệt đối của dữ liệu, cho phép thử nghiệm và kiểm chứng toàn diện phiên bản mới trước khi chính thức chuyển giao.", "Day 10 - Slide: Blue-Green Deployments for Data Pipelines"),
        ("Cold-to-Hot Data Lifecycle & Tiered Storage for AI Knowledge", "Một kho dữ liệu tri thức tích lũy 5 năm (hơn 100TB dữ liệu vector và text). Thiết kế Kiến trúc Lưu trữ Phân tầng (Tiered Knowledge Lifecycle) nào tối ưu hóa 80% chi phí lưu trữ mà không làm giảm tốc độ tra cứu các tài liệu thường dùng?",
         ["Lưu toàn bộ 100TB trong bộ nhớ RAM đắt tiền", "Phân chia 3 tầng lưu trữ: Hot Tier (Dữ liệu 30 ngày gần nhất và tài liệu truy cập cao lưu trên In-memory Vector DB/SSD siêu tốc); Warm Tier (Dữ liệu 1 năm lưu trên DiskANN SSD); Cold Tier (Dữ liệu cũ trên 1 năm lưu trên Object Storage S3 dạng nén Parquet), hỗ trợ truy xuất theo nhu cầu qua Query Federation", "Xóa toàn bộ dữ liệu cũ hơn 6 tháng", "In dữ liệu ra giấy để lưu trữ trong kho"], 1,
         "Tiered Storage tối ưu hóa chi phí phần cứng bằng cách phân bổ dữ liệu theo tần suất truy cập thực tế, kết hợp giữa tốc độ siêu tốc cho dữ liệu nóng và chi phí tối thiểu cho kho lưu trữ lạnh.", "Day 10 - Slide: Tiered Storage & Knowledge Lifecycle Management")
    ]
    add_day("Phase 1: COMP2010", "Day 10", "Data Pipeline & Observability", d10_easy, d10_med, d10_hard)

